class Rectangle {
    protected int width, height;
    public void setWidth(int w)  { width = w; }
    public void setHeight(int h) { height = h; }
    public int getArea() { return width * height; }
}
class Square extends Rectangle {
    public void setWidth(int w)  { width = w; height = w; }
    public void setHeight(int h) { width = h; height = h; }
}
public class Client {
    public static void main(String[] args) {
        Rectangle r = new Square();   // client thinks r is a Rectangle
        r.setWidth(5);
        r.setHeight(10);
        System.out.println(r.getArea());   // 100, not 50
    }
}

interface Database { void save(String order); }
class MySQLDatabase implements Database {
    public void save(String o) { System.out.println("MySQL saved " + o); }
}
class OrderService {                  // high-level module
    private final Database db;
    OrderService(Database db) { this.db = db; }   // injected
    void place(String o) { db.save(o); }
}
public class Main {
    public static void main(String[] args) {
        new OrderService(new MySQLDatabase()).place("#42");
    }
}

